  3113  // Runs in its own thread.
  3114  // Reads a block of text (SAM) and sends a new job to the thread queue to
  3115  // translate this to BAM.
  3116  static void *sam_dispatcher_read(void *vp) {
  3117      htsFile *fp = vp;
  3118      kstring_t line = {0};
  3119      int line_frag = 0;
  3120      SAM_state *fd = fp->state;
  3121      sp_lines *l = NULL;
  3122
  3123      // Pre-allocate buffer for left-over bits of line (exact size doesn't
  3124      // matter as it will grow if necessary).
  3125      if (ks_resize(&line, 1000) < 0)
  3126          goto err;
  3127
  3128      for (;;) {
  3129          // Check for command
  3130          pthread_mutex_lock(&fd->command_m);
  3131          switch (fd->command) {
  3132
  3133          case SAM_CLOSE:
  3134              pthread_cond_signal(&fd->command_c);
  3135              pthread_mutex_unlock(&fd->command_m);
  3136              hts_tpool_process_shutdown(fd->q);
  3137              goto tidyup;
  3138
  3139          default:
  3140              break;
  3141          }
  3142          pthread_mutex_unlock(&fd->command_m);
  3143
  3144          pthread_mutex_lock(&fd->lines_m);
  3145          if (fd->lines) {
  3146              // reuse existing line buffer
  3147              l = fd->lines;
  3148              fd->lines = l->next;
  3149          }
  3150          pthread_mutex_unlock(&fd->lines_m);
  3151
  3152          if (l == NULL) {
  3153              // none to reuse, to create a new one
  3154              l = calloc(1, sizeof(*l));
  3155              if (!l)
  3156                  goto err;
  3157              l->alloc = NM;
  3158              l->data = malloc(l->alloc+8); // +8 for optimisation in sam_parse1
  3159              if (!l->data) {
  3160                  free(l);
  3161                  l = NULL;
  3162                  goto err;
  3163              }
  3164              l->fd = fd;
  3165          }
  3166          l->next = NULL;
  3167
  3168          if (l->alloc < line_frag+NM/2) {
  3169              char *rp = realloc(l->data, line_frag+NM/2 +8);
  3170              if (!rp)
  3171                  goto err;
  3172              l->alloc = line_frag+NM/2;
  3173              l->data = rp;
  3174          }
  3175          memcpy(l->data, line.s, line_frag);
  3176
  3177          l->data_size = line_frag;
  3178          ssize_t nbytes;
  3179      longer_line:
  3180          if (fp->is_bgzf)
  3181              nbytes = bgzf_read(fp->fp.bgzf, l->data + line_frag, l->alloc - line_frag);
  3182          else
  3183              nbytes = hread(fp->fp.hfile, l->data + line_frag, l->alloc - line_frag);
  3184          if (nbytes < 0) {
  3185              sam_state_err(fd, errno ? errno : EIO);
  3186              goto err;
  3187          } else if (nbytes == 0)
  3188              break; // EOF
  3189          l->data_size += nbytes;
  3190
  3191          // trim to last \n. Maybe \r\n, but that's still fine
  3192          if (nbytes == l->alloc - line_frag) {
  3193              char *cp_end = l->data + l->data_size;
  3194              char *cp = cp_end-1;
  3195
  3196              while (cp > (char *)l->data && *cp != '\n')
  3197                  cp--;
  3198
  3199              // entire buffer is part of a single line
  3200              if (cp == l->data) {
  3201                  line_frag = l->data_size;
  3202                  char *rp = realloc(l->data, l->alloc * 2 + 8);
  3203                  if (!rp)
  3204                      goto err;
  3205                  l->alloc *= 2;
  3206                  l->data = rp;
  3207                  assert(l->alloc >= l->data_size);
  3208                  assert(l->alloc >= line_frag);
  3209                  assert(l->alloc >= l->alloc - line_frag);
  3210                  goto longer_line;
  3211              }
  3212              cp++;
  3213
  3214              // line holds the remainder of our line.
  3215              if (ks_resize(&line, cp_end - cp) < 0)
  3216                  goto err;
  3217              memcpy(line.s, cp, cp_end - cp);
  3218              line_frag = cp_end - cp;
  3219              l->data_size = l->alloc - line_frag;
  3220          } else {
  3221              // out of buffer
  3222              line_frag = 0;
  3223          }
  3224
  3225          l->serial = fd->serial++;
  3226          //fprintf(stderr, "Dispatching %p, %d bytes, serial %d\n", l, l->data_size, l->serial);
  3227          if (hts_tpool_dispatch3(fd->p, fd->q, sam_parse_worker, l,
  3228                                  cleanup_sp_lines, cleanup_sp_bams, 0) < 0)
  3229              goto err;
  3230          pthread_mutex_lock(&fd->command_m);
  3231          if (fd->command == SAM_CLOSE) {
  3232              pthread_mutex_unlock(&fd->command_m);
  3233              l = NULL;
  3234              goto tidyup;
  3235          }
  3236          l = NULL;  // Now "owned" by sam_parse_worker()
  3237          pthread_mutex_unlock(&fd->command_m);
  3238      }
  3239
  3240      if (hts_tpool_dispatch(fd->p, fd->q, sam_parse_eof, NULL) < 0)
  3241          goto err;
  3242
  3243      // At EOF, wait for close request.
  3244      // (In future if we add support for seek, this is where we need to catch it.)
  3245      for (;;) {
  3246          pthread_mutex_lock(&fd->command_m);
  3247          if (fd->command == SAM_NONE)
  3248              pthread_cond_wait(&fd->command_c, &fd->command_m);
  3249          switch (fd->command) {
  3250          case SAM_CLOSE:
  3251              pthread_cond_signal(&fd->command_c);
  3252              pthread_mutex_unlock(&fd->command_m);
  3253              hts_tpool_process_shutdown(fd->q);
  3254              goto tidyup;
  3255
  3256          default:
  3257              pthread_mutex_unlock(&fd->command_m);
  3258              break;
  3259          }
  3260      }
  3261
  3262   tidyup:
  3263      pthread_mutex_lock(&fd->command_m);
  3264      fd->command = SAM_CLOSE_DONE;
  3265      pthread_cond_signal(&fd->command_c);
  3266      pthread_mutex_unlock(&fd->command_m);
  3267
  3268      if (l) {
  3269          pthread_mutex_lock(&fd->lines_m);
  3270          l->next = fd->lines;
  3271          fd->lines = l;
  3272          pthread_mutex_unlock(&fd->lines_m);
  3273      }
  3274      free(line.s);
  3275
  3276      return NULL;
  3277
  3278   err:
  3279      sam_state_err(fd, errno ? errno : ENOMEM);
  3280      hts_tpool_process_shutdown(fd->q);
  3281      goto tidyup;
  3282  }
